// Diff readiness booleans against the previous run. Post only on change,
// and always on an alarm condition. Never emit secret, DSN or allowlist values.
const store = $getWorkflowStaticData('global');
const item = items[0].json;
const reachable = item.statusCode !== undefined && item.statusCode >= 200 && item.statusCode < 300;
const body = reachable ? (item.body || {}) : {};
const primary = body.langgraph_primary || {};

// Whitelist of booleans and counters we are allowed to report.
const watched = {
  reachable,
  paid_runs_enabled: body.paid_runs_enabled ?? null,
  configuration_valid: primary.configuration_valid ?? null,
  new_intake_owner: primary.new_intake_owner ?? null,
  intake_fencing_generation: primary.intake_fencing_generation ?? null,
  ambiguous_effect_count: primary.ambiguous_effect_count ?? null,
  paid_off_primary_intake_active: primary.paid_off_primary_intake_active ?? null,
  primary_runtime_active: primary.primary_runtime_active ?? null,
  legacy_new_intake_disabled: primary.legacy_new_intake_disabled ?? null,
  parallel_kill_switch: primary.parallel_kill_switch ?? null
};

const alarm =
  !reachable ||
  (typeof watched.ambiguous_effect_count === 'number' && watched.ambiguous_effect_count > 0) ||
  watched.parallel_kill_switch === true;

const previous = store.lastWatched ? JSON.parse(store.lastWatched) : null;
const changedKeys = previous
  ? Object.keys(watched).filter(k => JSON.stringify(watched[k]) !== JSON.stringify(previous[k]))
  : Object.keys(watched);

store.lastWatched = JSON.stringify(watched);

if (!alarm && changedKeys.length === 0) {
  return [];
}

const lines = changedKeys.map(k => {
  const before = previous ? JSON.stringify(previous[k]) : 'unset';
  return `• \`${k}\`: ${before} → ${JSON.stringify(watched[k])}`;
});

const header = alarm ? '*STATUS — attention*' : '*STATUS — readiness changed*';
const reasons = [];
if (!reachable) reasons.push('health endpoint unreachable');
if (typeof watched.ambiguous_effect_count === 'number' && watched.ambiguous_effect_count > 0) reasons.push('ambiguous effects present — rollback is blocked while this is non-zero');
if (watched.parallel_kill_switch === true) reasons.push('parallel kill switch engaged');

const text = [header, ...(reasons.length ? ['', ...reasons.map(r => `*${r}*`)] : []), '', ...lines].join('\n');
return [{ json: { text, alarm, changed: changedKeys } }];
